/**
 * dsh-web-launcher: one-click desktop launcher for the DeepSeek Harness Web
 * UI, plus a model-facing web_launcher tool.
 * @module dsh-web-launcher
 */

import z from '@deepseek-ai/schemastery'
import { defineTool } from '@deepseek-ai/dsh-tools'
import { fileURLToPath } from 'node:url'
import { ensureLauncher, ensureShortcut, openBrowser, resolveDesktopDir, resolveLauncherDir, serverStatus } from './launcher.js'

/** Stable Cordis plugin name; keep this stable after publishing. */
export const name = 'dsh-web-launcher'

/** Services required before load: the model-facing tool registry. */
export const inject = ['tools']

/** Loader-visible configuration schema and defaults. */
export const Config = z.object({
  autoInstall: z.boolean().default(true),
  createShortcut: z.boolean().default(true),
  port: z.number().default(3080),
  shortcutName: z.string().default('Start-DSH-Web.cmd'),
  linkName: z.string().default('DeepSeek Harness Web.lnk'),
  launcherDir: z.string().default(''),
  desktopDir: z.string().default(''),
})

/**
 * Resolve defaults for direct callers that bypass the Cordis Loader.
 * @param config - Partial serialized configuration.
 * @returns Configuration with all defaults applied.
 */
export function resolveConfig(config = {}) {
  return {
    autoInstall: config.autoInstall ?? true,
    createShortcut: config.createShortcut ?? true,
    port: config.port ?? 3080,
    shortcutName: config.shortcutName ?? 'Start-DSH-Web.cmd',
    linkName: config.linkName ?? 'DeepSeek Harness Web.lnk',
    launcherDir: config.launcherDir || resolveLauncherDir(),
    desktopDir: config.desktopDir || resolveDesktopDir(),
  }
}

/**
 * Apply the plugin to its Cordis context.
 * @param ctx - Scoped plugin context; the tool registration is owned by it.
 * @param config - Configuration resolved by Cordis from the exported schema.
 */
export function apply(ctx, config) {
  const resolved = resolveConfig(config)
  const logger = ctx.logger
  const iconPath = fileURLToPath(new URL('../icons/whale.ico', import.meta.url))

  if (process.platform === 'win32' && resolved.autoInstall) {
    try {
      const result = ensureLauncher(resolved)
      logger.info(`dsh-web-launcher: launcher ${result.created ? 'created' : 'refreshed'} at ${result.path}`)
    } catch (error) {
      logger.warn(`dsh-web-launcher: failed to write launcher: ${String(error)}`)
    }
    if (resolved.createShortcut) {
      try {
        const result = ensureShortcut({ ...resolved, iconPath })
        logger.info(`dsh-web-launcher: shortcut ${result.created ? 'created' : 'refreshed'} at ${result.path}`)
      } catch (error) {
        logger.warn(`dsh-web-launcher: failed to write shortcut: ${String(error)}`)
      }
    }
  } else if (process.platform !== 'win32') {
    logger.info('dsh-web-launcher: non-Windows host, desktop launcher skipped (web_launcher tool stays active)')
  }

  const webUrl = () => `http://127.0.0.1:${resolved.port}`

  ctx.tools.register(defineTool({
    name: 'web_launcher',
    description:
      'Manage the one-click DSH Web launcher on Windows and the Web UI itself. '
      + 'Actions: "install" creates or refreshes the desktop launcher "Start-DSH-Web.cmd" plus the app-style '
      + '"DeepSeek Harness Web.lnk" shortcut (black-whale icon) that boots `dsh web` and auto-opens the browser; '
      + '"open" opens the Web UI in the default browser; '
      + '"status" reports whether the DSH Web server is running on the configured port.',
    parameters: {
      action: {
        type: 'string',
        enum: ['install', 'open', 'status'],
        default: 'status',
        description: 'What to do with the launcher / Web UI.',
      },
    },
    output: {
      schema: {
        type: 'object',
        properties: {
          action: { type: 'string', description: 'The executed action.' },
          launcherPath: { type: 'string', description: 'Path of the desktop launcher (install action).' },
          running: { type: 'boolean', description: 'Whether the DSH Web server is running (status action).' },
          url: { type: 'string', description: 'The Web UI URL.' },
          message: { type: 'string', description: 'Human-readable outcome.' },
        },
        additionalProperties: false,
      },
      render: (_args, value) => [{ type: 'text', text: `[web_launcher] ${value.message}` }],
    },
    timeoutMs: 30_000,
    async execute(args) {
      const action = args?.action ?? 'status'
      const url = webUrl()
      if (action === 'install') {
        if (process.platform !== 'win32') {
          return { action, launcherPath: '', running: false, url, message: 'desktop launcher install is Windows-only' }
        }
        ensureLauncher(resolved)
        const result = ensureShortcut({ ...resolved, iconPath })
        return { action, launcherPath: result.path, running: false, url, message: `shortcut ${result.created ? 'created' : 'refreshed'} at ${result.path}` }
      }
      if (action === 'open') {
        openBrowser(url)
        return { action, launcherPath: '', running: false, url, message: `opened ${url} in the default browser` }
      }
      const status = await serverStatus(resolved.port)
      return {
        action,
        launcherPath: '',
        running: status.running,
        url,
        message: status.running
          ? `DSH Web is running at ${url}`
          : `DSH Web is not running at ${url} (start it with the desktop launcher or: dsh web --port ${resolved.port})`,
      }
    },
  }))
}
